#!/usr/bin/env python3
"""Build pristine scenario DBs and probe verifier rules with a no-op episode.

A rule that returns "complete" when final == initial (nothing was done) is
lenient: it would credit trajectories that never satisfied the task.
"""
import json
import os
import re
import sqlite3
import sys
from pathlib import Path

ROOT = Path("/workspace")
DATA = ROOT / "data/AgentWorldModel-1K"
OUT = Path("/tmp/noop")
OUT.mkdir(parents=True, exist_ok=True)


def norm(s):
    s = s.lower()
    s = re.sub(r"[^a-z0-9_]", "_", s)
    return re.sub(r"_+", "_", s).strip("_").strip()


def load(name):
    with (DATA / f"{name}.jsonl").open() as fh:
        return [json.loads(line) for line in fh if line.strip()]


def build_db(scenario, schemas, samples):
    path = OUT / f"{norm(scenario)}.db"
    if path.exists():
        return str(path)
    schema = next(s for s in schemas if norm(s["scenario"]) == norm(scenario))
    sample = next((s for s in samples if norm(s["scenario"]) == norm(scenario)), None)
    conn = sqlite3.connect(str(path))
    cur = conn.cursor()
    for table in schema["db_schema"].get("tables", []):
        try:
            cur.execute(table["ddl"])
            for idx in table.get("indexes", []):
                cur.execute(idx)
        except Exception:
            pass
    conn.commit()
    if sample:
        cur.execute("PRAGMA foreign_keys = ON;")
        for tbl in sample["sample_data"].get("tables", []):
            for stmt in tbl.get("insert_statements", []):
                try:
                    cur.execute(stmt)
                except Exception:
                    pass
        conn.commit()
    conn.close()
    return str(path)


def run_rule(code, func_name, initial, final, answer=""):
    ns = {"sqlite3": sqlite3, "json": json, "os": os, "re": re, "__builtins__": __builtins__}
    try:
        exec(code, ns)
    except Exception as exc:
        return "exec_error", f"{type(exc).__name__}: {exc}"
    fn = ns.get(func_name)
    if not fn:
        return "no_func", func_name
    try:
        res = fn(initial_db_path=initial, final_db_path=final, final_answer=answer)
    except TypeError:
        try:
            res = fn(initial, final, answer)
        except Exception as exc:
            return "call_error", f"{type(exc).__name__}: {exc}"
    except Exception as exc:
        return "call_error", f"{type(exc).__name__}: {exc}"
    if not isinstance(res, dict) or "result" not in res:
        return "bad_format", str(type(res).__name__)
    val = res.get("result", "others")
    return (val if val in ("complete", "others") else "others"), None


def main():
    only = sys.argv[1] if len(sys.argv) > 1 else None
    recs = load("gen_verifier.pure_code")
    schemas = load("gen_db")
    samples = load("gen_sample")

    if only == "test":
        import pyarrow.parquet as pq
        rows = pq.read_table(DATA / "verl/test.parquet").to_pylist()
        want = {(r["env_kwargs"]["scenario"], r["env_kwargs"]["task_idx"]) for r in rows}
    else:
        want = None

    seen = {}
    selected = []
    for i, r in enumerate(recs):
        key = (norm(r["scenario"]), r["task_idx"])
        if key in seen:
            continue  # find_scenario_entry returns FIRST match
        seen[key] = i
        selected.append((i, r))

    print(f"rules selected by bridge first-match: {len(selected)} / {len(recs)}")
    targets = [(i, r) for i, r in selected if want is None or (norm(r["scenario"]), r["task_idx"]) in want]
    print(f"probing {len(targets)} rules")

    dbcache = {}
    stats = {"complete": [], "others": 0, "exec_error": [], "call_error": [], "no_func": [], "bad_format": []}
    for n, (i, r) in enumerate(targets):
        sc = norm(r["scenario"])
        if sc not in dbcache:
            try:
                dbcache[sc] = build_db(r["scenario"], schemas, samples)
            except Exception as exc:
                dbcache[sc] = None
        db = dbcache[sc]
        if not db:
            continue
        code = r["verification"]["code"]
        fn = "verify_task_completion"
        for line in code.split("\n"):
            line = line.strip()
            if line.startswith("def verify_") and "(" in line:
                fn = line.split("(")[0].replace("def ", "").strip()
                break
        val, err = run_rule(code, fn, db, db, "")
        if val == "complete":
            stats["complete"].append((i, r["scenario"], r["task_idx"]))
        elif val == "others":
            stats["others"] += 1
        else:
            stats[val].append((i, r["scenario"], r["task_idx"], err))
        if (n + 1) % 500 == 0:
            print(f"  ..{n+1}", flush=True)

    print("\n=== NO-OP PROBE RESULTS ===")
    print("correctly returned 'others':", stats["others"])
    print("LENIENT (returned 'complete' on no-op):", len(stats["complete"]))
    for x in stats["complete"][:60]:
        print("   ", x)
    for k in ("exec_error", "call_error", "no_func", "bad_format"):
        print(f"{k}: {len(stats[k])}")
        for x in stats[k][:20]:
            print("   ", x)


if __name__ == "__main__":
    main()

