#!/usr/bin/env python3
"""Compare shadowed original vs appended replacement rules under AWM's real deps.

awm_source/pyproject.toml lists no pytz and no python-dateutil, so the AWM
verifier subprocess cannot import them.  Simulate that runtime by blocking
both modules, then run each rule version on a no-op episode.
"""
import builtins
import json
import os
import re
import sqlite3
import sys
from pathlib import Path

ROOT = Path("/workspace")
DATA = ROOT / "data/AgentWorldModel-1K"
sys.path.insert(0, "/tmp")
from noop_probe import build_db, load, norm  # noqa: E402

BLOCKED = {"pytz", "dateutil", "dateutil.relativedelta"}
_real_import = builtins.__import__


def guarded(name, *a, **k):
    if name in BLOCKED or name.split(".")[0] in BLOCKED:
        raise ModuleNotFoundError(f"No module named '{name}'")
    return _real_import(name, *a, **k)


def run(code, initial, final, answer=""):
    ns = {"sqlite3": sqlite3, "json": json, "os": os, "re": re, "__builtins__": builtins.__dict__}
    try:
        exec(code, ns)
    except Exception as exc:
        return "EXEC_ERROR", f"{type(exc).__name__}: {exc}"
    fn = None
    for line in code.split("\n"):
        s = line.strip()
        if s.startswith("def verify_") and "(" in s:
            fn = s.split("(")[0].replace("def ", "").strip()
            break
    fn = fn or "verify_task_completion"
    if fn not in ns:
        return "NO_FUNC", fn
    try:
        res = ns[fn](initial_db_path=initial, final_db_path=final, final_answer=answer)
    except Exception as exc:
        return "CALL_ERROR", f"{type(exc).__name__}: {exc}"
    if not isinstance(res, dict) or "result" not in res:
        return "BAD_FORMAT", str(type(res).__name__)
    return res.get("result"), None


def main():
    builtins.__import__ = guarded
    recs = load("gen_verifier.pure_code")
    schemas = load("gen_db")
    samples = load("gen_sample")
