def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    from typing import List, Tuple, Any, Dict

    def safe_query(db_path: str, query: str, params: tuple = ()) -> List[Dict[str, Any]]:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cur = conn.cursor()
            cur.execute(query, params)
            rows = cur.fetchall()
            cur.close()
            conn.close()
            return [dict(r) for r in rows]
        except Exception:
            return []

    # 1) Locate Emergency Fund category in final DB (budget_id=1)
    cat_rows = safe_query(final_db_path, "SELECT id, user_id, budget_id FROM categories WHERE budget_id = ? AND name = ?", (1, 'Emergency Fund'))
    if len(cat_rows) != 1:
        return {"result": "others"}
    cat_id = cat_rows[0].get('id')
    if not isinstance(cat_id, int):
        return {"result": "others"}

    # 2) Verify goal exists and matches requirements
    goal_rows = safe_query(final_db_path, "SELECT goal_type, target_amount, target_date FROM category_goals WHERE user_id = ? AND category_id = ?", (1, cat_id))
    if len(goal_rows) != 1:
        return {"result": "others"}
    g = goal_rows[0]
    goal_type = g.get('goal_type')
    target_amount_val = g.get('target_amount')
    target_date = g.get('target_date')
    try:
        target_amount = float(target_amount_val)
    except Exception:
        return {"result": "others"}
    if goal_type != 'target_balance_by_date':
        return {"result": "others"}
    if abs(target_amount - 5000.0) > 0.01:
        return {"result": "others"}
    if target_date != '2025-12-31':
        return {"result": "others"}

    # 3) Identify current month (fixed as 2025-03 per scenario) and get its budget_month_id
    bm_rows = safe_query(final_db_path, "SELECT id, month FROM budget_months WHERE budget_id = ? AND month = ?", (1, '2025-03'))
    if len(bm_rows) != 1:
        return {"result": "others"}
    bm_id = bm_rows[0].get('id')
    current_month_str = bm_rows[0].get('month')
    if not isinstance(bm_id, int) or not isinstance(current_month_str, str):
        return {"result": "others"}

    # 4) Get March 2025 budget allocation for Emergency Fund
    alloc_rows = safe_query(final_db_path, "SELECT budgeted_amount FROM budget_allocations WHERE budget_month_id = ? AND category_id = ?", (bm_id, cat_id))
    if len(alloc_rows) != 1:
