        if not isinstance(s, str) or len(s) < 7 or s[4] != '-' or s[5:7].isdigit() is False:
            return None
        try:
            y = int(s[0:4])
            m = int(s[5:7])
            if 1 <= m <= 12:
                return (y, m)
            return None
        except Exception:
            return None

    cm_parsed = parse_year_month(current_month_str)
