        m2 = int(target_date[5:7])
    except Exception:
        return {"result": "others"}

    # 5) Compute months remaining inclusive from current month to target month
    months_remaining = (y2 - y1) * 12 + (m2 - m1) + 1
    if months_remaining < 0:
