        (1, 1, cat_id, current_month_start)
    )
    existing_activity = 0.0
    if len(sum_rows) == 1:
        try:
            existing_activity = float(sum_rows[0].get('total') or 0.0)
        except Exception:
            existing_activity = 0.0

    # 7) Calculate required monthly contribution
    needed_total_remaining = target_amount - existing_activity
    if needed_total_remaining < 0:
        needed_total_remaining = 0.0
    if months_remaining <= 0:
        required_monthly = 0.0
    else:
        required_monthly = needed_total_remaining / months_remaining

    # 8) Verify March budgeted amount is sufficient
    epsilon = 0.005
    if budgeted_amount + epsilon >= required_monthly - epsilon:
        return {"result": "complete"}

    return {"result": "others"}
